// This code snippet is a qualitative representation of the concept of ending clock changing.

public class ClockChangePolicy {
    private boolean isClockChangingEnded;

    public ClockChangePolicy() {
        this.isClockChangingEnded = false; // Initially, clock changing is not ended
    }

    public void endClockChanging() {
        this.isClockChangingEnded = true; // Method to end clock changing
    }

    public boolean isClockChangingEnded() {
        return this.isClockChangingEnded; // Check if clock changing has ended
    }

    public static void main(String[] args) {
        ClockChangePolicy policy = new ClockChangePolicy();
        System.out.println(Clock changing ended:  + policy.isClockChangingEnded());
        policy.endClockChanging();
        System.out.println(Clock changing ended:  + policy.isClockChangingEnded());
    }
}

