function checkBathroomAccess(userGender, bathroomGender) {
    // Check if the user's gender matches the bathroom's designated gender
    if (userGender === bathroomGender) {
        return Access granted;
    } else {
        // Provide alternative options or guidance
        return Please use the gender-neutral bathroom or seek assistance.;
    }
}

