def analyze_text(text):
    concerns = {
        discrimination: False,
        identity_complexity: False,
        legal_safeguards: False,
        social_safeguards: False
    }

    for theme in themes.values():
        for keyword in theme[keywords]:
            if keyword in text:
                if discrimination in theme[description]:
                    concerns[discrimination] = True
                if identity in theme[description]:
                    concerns[identity_complexity] = True
                if legal in theme[description]:
                    concerns[legal_safeguards] = True
                if social in theme[description]:
                    concerns[social_safeguards] = True

    return concerns

# Example usage
