// This code is designed to address the issue of unwanted yard visitors.

function detectUnwantedVisitors(yard) {
    const unwantedVisitors = ['raccoon', 'squirrel', 'stray cat'];
    let detectedVisitors = [];

    yard.forEach(visitor => {
        if (unwantedVisitors.includes(visitor)) {
            detectedVisitors.push(visitor);
        }
    });

    return detectedVisitors;
}

function alertHomeowner(detectedVisitors) {
    if (detectedVisitors.length > 0) {
        console.log('Alert: Unwanted visitors detected in the yard:', detectedVisitors);
    } else {
        console.log('No unwanted visitors detected.');
    }
}

// Example usage:
const yardVisitors = ['bird', 'raccoon', 'dog'];
const detectedVisitors = detectUnwantedVisitors(yardVisitors);
alertHomeowner(detectedVisitors);

