# Theme 1: Professional Misconduct and Reputation
professional_misconduct_and_reputation = {
    Professional Exploitation: Involves unethical behavior such as trading sex for lower bills, potentially involving clients.,
    Reputation Consequences: The impact of his personal life on his professional image, with negative online presence affecting his career.
}

# Theme 2: Public Scrutiny and Accountability
public_scrutiny_and_accountability = {
    Public Exposure/Shaming: The widespread online allegations and shaming through platforms like Liars, Cheaters R Us, and Cheater Report.,
    Lack of Accountability/Denial: Failure to address his issues through counseling and current lack of effort in damage control.
}

# Theme 3: Behavioral Patterns and Mental Health
behavioral_patterns_and_mental_health = {
    Serial Cheating/Infidelity: His reputation as a 'serial cheater' and the pattern of infidelity.,
    Mental Health Concerns: The description of him as a 'very sick individual,' indicating potential psychological issues.
}

# Theme 4: Gender Dynamics
gender_dynamics = {
    Exploitation of Women: The involvement of multiple women, suggesting potential gender-related exploitation.
}

# Consolidated Themes
themes = {
    Professional Misconduct and Reputation: professional_misconduct_and_reputation,
    Public Scrutiny and Accountability: public_scrutiny_and_accountability,
    Behavioral Patterns and Mental Health: behavioral_patterns_and_mental_health,
    Gender Dynamics: gender_dynamics
}

# Print the themes for verification
for theme, subthemes in themes.items():
    print(fTheme: {theme})
    for subtheme, description in subthemes.items():
        print(f  Sub-theme: {subtheme} - {description})

